-- Speeds the hot inbox query:
-- GET /api/emails?status=Unanswered&limit=50
--
-- The predicate mirrors the SQL generated by emailFilterSql() for Unanswered:
-- not trashed, not outbound, response_at is null. Company sender filtering remains
-- a runtime predicate because the configured mailbox list can vary by environment.
create index concurrently if not exists app_emails_unanswered_page_idx
on app_emails (received_at desc nulls last, id desc)
where
  not ((coalesce(data->>'trashed_at', '') <> '' or coalesce(data->>'dashboard_folder', '') = 'trash' or coalesce(data->'gmail_labels', '[]'::jsonb) ? 'TRASH'))
  and not (coalesce(data->>'direction', '') = 'outbound')
  and response_at is null;
